#!/usr/bin/env python3
"""Adds CarryMe's Android settings to the files generated by `flutter create`.

Run from the project root after `flutter create --platforms=android .`
It is safe to run more than once.
"""
import pathlib
import re
import sys

MANIFEST = pathlib.Path("android/app/src/main/AndroidManifest.xml")

PERMISSIONS = [
    "android.permission.INTERNET",
    "android.permission.ACCESS_NETWORK_STATE",
    "android.permission.ACCESS_FINE_LOCATION",
    "android.permission.ACCESS_COARSE_LOCATION",
]

QUERIES = """
        <intent>
            <action android:name="android.intent.action.VIEW" />
            <data android:scheme="https" />
        </intent>
        <intent>
            <action android:name="android.intent.action.DIAL" />
            <data android:scheme="tel" />
        </intent>
        <intent>
            <action android:name="android.intent.action.SENDTO" />
            <data android:scheme="sms" />
        </intent>"""


def main() -> int:
    if not MANIFEST.exists():
        print(f"{MANIFEST} not found - run `flutter create --platforms=android .` first")
        return 1
    xml = MANIFEST.read_text(encoding="utf-8")

    # 1. Permissions, placed right after the <manifest ...> opening tag.
    missing = [p for p in PERMISSIONS if p not in xml]
    if missing:
        lines = "".join(f'\n    <uses-permission android:name="{p}" />' for p in missing)
        xml = re.sub(r"(<manifest[^>]*>)", lambda m: m.group(1) + lines, xml, count=1)

    # 2. App name shown under the launcher icon.
    xml = re.sub(r'android:label="[^"]*"', 'android:label="CarryMe"', xml, count=1)

    # 3. Intent queries so phone calls, SMS and links open on Android 11+.
    if 'android:scheme="tel"' not in xml:
        if "<queries>" in xml:
            xml = xml.replace("<queries>", "<queries>" + QUERIES, 1)
        else:
            xml = xml.replace("</manifest>", "    <queries>" + QUERIES + "\n    </queries>\n</manifest>", 1)

    MANIFEST.write_text(xml, encoding="utf-8")
    print("AndroidManifest.xml patched for CarryMe")
    patch_min_sdk()
    return 0


def patch_min_sdk() -> None:
    """Firebase needs Android 6.0+ (minSdk 23)."""
    for path in (pathlib.Path("android/app/build.gradle.kts"), pathlib.Path("android/app/build.gradle")):
        if not path.exists():
            continue
        text = path.read_text(encoding="utf-8")
        if "CARRYME_MIN_SDK" in text:
            return
        kts = path.suffix == ".kts"
        expr = "maxOf(23, flutter.minSdkVersion)" if kts else "Math.max(23, flutter.minSdkVersion)"
        new = re.sub(r"(minSdk(?:Version)?\s*=?\s*)flutter\.minSdkVersion", r"\g<1>" + expr + " // CARRYME_MIN_SDK", text, count=1)
        if new == text:
            print(f"WARNING: could not find minSdk in {path}; set it to 23 or higher by hand")
            return
        path.write_text(new, encoding="utf-8")
        print(f"{path}: minSdk set to at least 23")
        return
    print("WARNING: android/app/build.gradle(.kts) not found")


if __name__ == "__main__":
    sys.exit(main())
